# Generated by Google Gemini

def _extract_host(raw_value):
    first_item, _, _ = raw_value.partition(",")
    host_only, _, _ = first_item.strip().lower().partition(":")
    return host_only


class AzureFrontDoorMiddleware:
    def __init__(self, app, fdid="", allow_hosts=""):
        self.app = app
        self.fdid = fdid.strip()
        self.allow_hosts = {
            _extract_host(h) for h in allow_hosts.split(",") if h.strip()
        }

    def __call__(self, environ, start_response):
        req_fdid = environ.get("HTTP_X_AZURE_FDID", "").strip()
        current_host = _extract_host(environ.get("HTTP_HOST", ""))

        is_valid_afd = bool(self.fdid and req_fdid == self.fdid)
        is_allowed_exception = current_host in self.allow_hosts

        if not is_valid_afd and not is_allowed_exception:
            start_response("403 Forbidden", [("Content-Type", "text/plain; charset=utf-8")])
            return [b"Forbidden: Invalid or missing X-Azure-FDID"]

        if is_valid_afd:
            xf_host = environ.get("HTTP_X_FORWARDED_HOST")
            xf_proto = environ.get("HTTP_X_FORWARDED_PROTO", "https")

            first_proto, _, _ = xf_proto.partition(",")
            proto = first_proto.strip().lower() or "https"
            default_port = "443" if proto == "https" else "80"

            environ["wsgi.url_scheme"] = proto
            environ["SERVER_PORT"] = default_port

            if xf_host:
                first_host, _, _ = xf_host.partition(",")
                clean_host = first_host.strip()
                host_only, _, port_part = clean_host.partition(":")

                if port_part and port_part not in ("80", "443"):
                    environ["HTTP_HOST"] = clean_host
                    environ["SERVER_PORT"] = port_part
                else:
                    environ["HTTP_HOST"] = host_only

                environ["SERVER_NAME"] = host_only

        return self.app(environ, start_response)


def make_afd_middleware(app, global_conf, fdid="", allow_hosts=""):
    return AzureFrontDoorMiddleware(
        app,
        fdid=fdid,
        allow_hosts=allow_hosts,
    )
